alter policy "Scoped visibility for apostila_chapters" on public.apostila_chapters using ((has_role((select auth.uid()), 'admin'::app_role) OR (EXISTS ( SELECT 1
   FROM (apostila_modules m
     JOIN apostilas a ON ((a.id = m.apostila_id)))
  WHERE ((m.id = apostila_chapters.module_id) AND (a.published = true) AND (((get_content_scope((select auth.uid())) = 'full'::text) AND ((a.category IS NULL) OR (a.category <> ALL (ARRAY['ENEM'::text, 'Simulados ENEM'::text])))) OR ((get_content_scope((select auth.uid())) = 'enem_only'::text) AND (a.category = ANY (ARRAY['ENEM'::text, 'Simulados ENEM'::text])))))))));
