alter policy "Authenticated can view scoped materials" on public.materials using ((has_role((select auth.uid()), 'admin'::app_role) OR (EXISTS ( SELECT 1
   FROM (apostila_materials am
     JOIN apostilas a ON ((a.id = am.apostila_id)))
  WHERE ((am.material_id = materials.id) AND (a.published = true) AND (((get_content_scope((select auth.uid())) = 'full'::text) AND ((a.category IS NULL) OR (a.category <> ALL (ARRAY['ENEM'::text, 'Simulados ENEM'::text])))) OR ((get_content_scope((select auth.uid())) = 'enem_only'::text) AND (a.category = ANY (ARRAY['ENEM'::text, 'Simulados ENEM'::text]))))))) OR (EXISTS ( SELECT 1
   FROM categories c
  WHERE ((c.id = materials.category_id) AND (((get_content_scope((select auth.uid())) = 'enem_only'::text) AND (c.slug ~~ 'enem-%'::text)) OR ((get_content_scope((select auth.uid())) = 'full'::text) AND (c.slug !~~ 'enem-%'::text))))))));
